<#
.SYNOPSIS
    [Intune Script] Windows - National Minute of Silence Reminder
    Deploys the daily National Minute of Silence reminder at 09:00 for Windows devices.

.DESCRIPTION
    Designed for Microsoft Intune (Devices > Scripts > Windows).
    - Intune settings:
        * Run this script using the logged on credentials: Yes (RunAsAccount: user)
        * Enforce script signature check: No
        * Run script in 64-bit PowerShell: Yes
    - Actions:
        1. Deploys the WPF notification script (with UTF-8 BOM) to %LOCALAPPDATA%\Corporate\MinuteOfSilence.
        2. Registers a daily Windows Scheduled Task at 08:59:50 local time (pre-warmed for 09:00:00).
        3. Configures battery execution, single-instance guard, audio caching, and NTP time guard.

.NOTES
    Complies with Jira II-5426 and Intune naming conventions:
    "Windows - <Action / Purpose>"
    Pure ASCII outer script to prevent Windows PowerShell 5.1 encoding parser errors when Intune strips UTF-8 BOM.
#>
[CmdletBinding()]
param()

$ErrorActionPreference = 'Stop'

Write-Host "=== [Intune] Windows - National Minute of Silence Reminder ===" -ForegroundColor Cyan

# -- 1. Resolve target installation directory ----------------------------------
$InstallDir = Join-Path $env:LOCALAPPDATA "Corporate\MinuteOfSilence"
if (-not $env:LOCALAPPDATA -or $env:USERNAME -eq "SYSTEM") {
    $InstallDir = "C:\ProgramData\Corporate\MinuteOfSilence"
}

if (-not (Test-Path $InstallDir)) {
    New-Item -Path $InstallDir -ItemType Directory -Force | Out-Null
    Write-Host "Created directory: $InstallDir" -ForegroundColor Gray
}

$PayloadPath = Join-Path $InstallDir "Show-MinuteOfSilence.ps1"
$AudioPath   = Join-Path $InstallDir "metronome.mp3"
$AudioUrl    = "https://sainfraartifacts01.blob.core.windows.net/public/minute-of-silence/metronome.mp3"
$TaskName    = "National Minute of Silence Reminder"

# Download and cache the metronome audio track from GitHub
if (-not (Test-Path $AudioPath) -or (Get-Item $AudioPath).Length -lt 100000) {
    try {
        Write-Host "Downloading metronome audio track from GitHub ($AudioUrl)..." -ForegroundColor Cyan
        [Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12
        Invoke-WebRequest -Uri $AudioUrl -OutFile $AudioPath -UseBasicParsing -TimeoutSec 15
        Write-Host "Audio track downloaded: $AudioPath" -ForegroundColor Green
    } catch {
        Write-Warning "Failed to download audio track: $_. Built-in synthesizer fallback will be used."
    }
}

# -- 2. Write UTF-8-BOM Base64 payload -----------------------------------------
$PayloadB64 = ''

$payloadBytes = [System.Convert]::FromBase64String($PayloadB64.Trim())
[System.IO.File]::WriteAllBytes($PayloadPath, $payloadBytes)
Write-Host "Payload written to: $PayloadPath" -ForegroundColor Green

# -- 3. Register Windows Scheduled Task ----------------------------------------
Write-Host "Registering daily scheduled task '$TaskName' for 09:00..." -ForegroundColor Cyan

$action = New-ScheduledTaskAction `
    -Execute "powershell.exe" `
    -Argument "-NoProfile -ExecutionPolicy Bypass -WindowStyle Hidden -File `"$PayloadPath`""

$trigger = New-ScheduledTaskTrigger -Daily -At "08:59:50"

$settings = New-ScheduledTaskSettingsSet `
    -AllowStartIfOnBatteries `
    -DontStopIfGoingOnBatteries `
    -StartWhenAvailable `
    -ExecutionTimeLimit (New-TimeSpan -Minutes 2) `
    -MultipleInstances IgnoreNew

$existingTask = Get-ScheduledTask -TaskName $TaskName -ErrorAction SilentlyContinue
if (-not $existingTask) {
    $registeredTask = Register-ScheduledTask `
        -TaskName $TaskName `
        -Action $action `
        -Trigger $trigger `
        -Settings $settings `
        -Description "Daily National Minute of Silence reminder at 09:00" `
        -Force
    Write-Host "SUCCESS: Scheduled task '$TaskName' registered. Next run at 09:00." -ForegroundColor Green
} else {
    try {
        Register-ScheduledTask `
            -TaskName $TaskName `
            -Action $action `
            -Trigger $trigger `
            -Settings $settings `
            -Description "Daily National Minute of Silence reminder at 09:00" `
            -Force -ErrorAction Stop | Out-Null
        Write-Host "SUCCESS: Scheduled task '$TaskName' updated. Next run at 09:00." -ForegroundColor Green
    } catch {
        Write-Host "SUCCESS: Scheduled task '$TaskName' already registered and payload updated." -ForegroundColor Green
    }
}
exit 0